import{a as e,i as t,r as n,s as r,t as i}from"./app-CchzzT6L.js";var a=JSON.parse(`{"path":"/youtube/mongo-db-principle.html","title":"MongoDB Principle","lang":"en-US","frontmatter":{},"git":{"updatedTime":1750343135000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":2,"url":"https://github.com/hifat"}],"changelog":[{"hash":"a33e6630a9f8964acce6eb994d47e496cecbe794","time":1750343135000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add mongo db topic"},{"hash":"557ecea12e09a9f0ae254242fa18bdaf440dfb82","time":1750342808000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add mongo db principle content"}]},"filePathRelative":"youtube/mongo-db-principle.md"}`),o={name:`mongo-db-principle.md`};function s(i,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[n(`h1`,{id:`mongodb-principle`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#mongodb-principle`},[n(`span`,null,`MongoDB Principle`)])],-1),n(`iframe`,{width:`100%`,height:`500`,src:`https://www.youtube.com/embed/xY2NwsYHpV4`,title:`golang obfuscated malware goes crazy`,frameborder:`0`,allow:`accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share`,referrerpolicy:`strict-origin-when-cross-origin`,allowfullscreen:``},null,-1),e(`<p>ในวิดีโอนี้ คุณ Xen และ Frank ได้มานำเสนอเกี่ยวกับ <strong>MongoDB Performance: Patterns and Best Practices</strong> โดยมีจุดประสงค์เพื่อให้ผู้ฟังได้รับความรู้และเทคนิคใหม่ๆ ที่สามารถนำไปปรับใช้ในการปรับแต่งและจัดการประสิทธิภาพของ MongoDB ได้อย่างมีประสิทธิภาพครับ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=74" target="_blank" rel="noopener noreferrer">01:14</a>]</p><h3 id="ภาพรวมของเนื้อหาในวิดีโอ" tabindex="-1"><a class="header-anchor" href="#ภาพรวมของเนื้อหาในวิดีโอ"><span>ภาพรวมของเนื้อหาในวิดีโอ</span></a></h3><p>วิดีโอนี้จะเน้นไปที่ 12 รูปแบบ (patterns) และแนวปฏิบัติที่ดีที่สุด (best practices) สำหรับการปรับแต่งประสิทธิภาพของแอปพลิเคชันและ database [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=86" target="_blank" rel="noopener noreferrer">01:26</a>] โดยรูปแบบเหล่านี้จะถูกจัดกลุ่มออกเป็น 4 หมวดหมู่หลัก [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=282" target="_blank" rel="noopener noreferrer">04:42</a>] ได้แก่:</p><ul><li><strong>Big Picture</strong>: การทำความเข้าใจภาพรวมของระบบและข้อกำหนด [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=289" target="_blank" rel="noopener noreferrer">04:49</a>]</li><li><strong>Query and Indexes</strong>: การออกแบบ query และการใช้ index อย่างมีประสิทธิภาพ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=391" target="_blank" rel="noopener noreferrer">06:31</a>]</li><li><strong>Sharding and Scaling</strong>: กลยุทธ์ในการ scale และ sharding [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=494" target="_blank" rel="noopener noreferrer">08:14</a>]</li><li><strong>Put it Together</strong>: การนำทุกอย่างมารวมกัน [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=297" target="_blank" rel="noopener noreferrer">04:57</a>]</li></ul><p>ในเวลา 45 นาทีที่จำกัด ผู้บรรยายจะแนะนำแต่ละ pattern อย่างรวดเร็ว และจะเจาะลึก 3 patterns ที่สำคัญ โดยมี 2 patterns ที่เลือกไว้ล่วงหน้า และอีก 1 pattern ที่ผู้ฟังร่วมกันโหวต [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=107" target="_blank" rel="noopener noreferrer">01:47</a>] นอกจากนี้ยังมีการสาธิตฟีเจอร์ใหม่ๆ ที่จะมาใน MongoDB Atlas อีกด้วย [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=128" target="_blank" rel="noopener noreferrer">02:08</a>]</p><h3 id="_4-ขั้นตอนการคิดในการปรับแต่งประสิทธิภาพ" tabindex="-1"><a class="header-anchor" href="#_4-ขั้นตอนการคิดในการปรับแต่งประสิทธิภาพ"><span>4 ขั้นตอนการคิดในการปรับแต่งประสิทธิภาพ</span></a></h3><p>รูปแบบทั้ง 12 patterns จะถูกจัดเรียงตามกระบวนการคิด 4 ขั้นตอน ได้แก่:</p><ol><li><strong>Context (บริบท)</strong>: ทำความเข้าใจสถานการณ์ที่เกิดปัญหา [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=163" target="_blank" rel="noopener noreferrer">02:43</a>]</li><li><strong>Problem (ปัญหา)</strong>: ระบุปัญหาที่ต้องการแก้ไข [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=170" target="_blank" rel="noopener noreferrer">02:50</a>]</li><li><strong>Force (แรงต้าน/ข้อจำกัด)</strong>: พิจารณาเงื่อนไขที่ขัดแย้งกัน หรือสิ่งที่ต้องประนีประนอม [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=176" target="_blank" rel="noopener noreferrer">02:56</a>]</li><li><strong>Solution (แนวทางแก้ไข)</strong>: วิธีการแก้ปัญหา [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=191" target="_blank" rel="noopener noreferrer">03:11</a>]</li></ol><p>ผู้บรรยายได้ยกตัวอย่างธุรกิจ Delivery อาหารออร์แกนิกที่ประสบความสำเร็จอย่างรวดเร็ว ซึ่งนำไปสู่ปัญหาในการ scale application และ database [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=205" target="_blank" rel="noopener noreferrer">03:25</a>] และต้องใช้เวลาในการทำ performance tuning เพื่อให้ database รองรับความต้องการที่เพิ่มขึ้น [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=240" target="_blank" rel="noopener noreferrer">04:00</a>] ซึ่งนี่คือปัญหาที่วิดีโอนี้จะช่วยแนะนำแนวทางแก้ไข</p><h3 id="การเจาะลึก-3-patterns-ที่สําคัญ" tabindex="-1"><a class="header-anchor" href="#การเจาะลึก-3-patterns-ที่สําคัญ"><span>การเจาะลึก 3 Patterns ที่สำคัญ</span></a></h3><h4 id="_1-hunt-bottlenecks-การระบุปัญหาคอขวด" tabindex="-1"><a class="header-anchor" href="#_1-hunt-bottlenecks-การระบุปัญหาคอขวด"><span>1. Hunt Bottlenecks (การระบุปัญหาคอขวด)</span></a></h4><p>Frank ได้นำเสนอวิธี &quot;Hunt Bottlenecks&quot; หรือการค้นหาคอขวดใน MongoDB Atlas โดยเปรียบเทียบกับการหากลุ่มดาวในท้องฟ้า [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1425" target="_blank" rel="noopener noreferrer">23:45</a>]</p><ul><li><strong>ปัญหา</strong>: แอปพลิเคชันทำงานช้า ลูกค้าแจ้งว่าเว็บไซต์โหลดนาน [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1636" target="_blank" rel="noopener noreferrer">27:16</a>]</li><li><strong>เครื่องมือใน Atlas</strong>: <ul><li><strong>Metrics Chart</strong>: ดูภาพรวมของ metrics ต่างๆ เช่น จำนวน operation และเวลาที่ใช้ในการ execution [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1672" target="_blank" rel="noopener noreferrer">27:52</a>]</li><li><strong>Query Insights Tab</strong>: วิเคราะห์ latency ในระดับ collection ช่วยให้ระบุได้ว่า collection ใดมี latency สูงกว่าปกติ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1717" target="_blank" rel="noopener noreferrer">28:37</a>] ในตัวอย่างพบว่า <code>transactions</code> collection มี latency สูงขึ้น [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1739" target="_blank" rel="noopener noreferrer">28:59</a>]</li><li><strong>Query Profiler</strong>: ตรวจสอบ individual slow operations ที่เกิดขึ้นใน database โดยแสดงรายละเอียด เช่น namespace, host, และ command ที่รัน [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1804" target="_blank" rel="noopener noreferrer">30:04</a>] ซึ่งในตัวอย่างพบว่ามีการทำ <code>collection scan</code> บน <code>transactions</code> collection จำนวนมาก [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1837" target="_blank" rel="noopener noreferrer">30:37</a>]</li><li><strong>Atlas Performance Advisor</strong>: แนะนำการปรับปรุงประสิทธิภาพ database โดยจะ scan slow query logs และให้คำแนะนำ เช่น การสร้าง index [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1897" target="_blank" rel="noopener noreferrer">31:37</a>] ในตัวอย่างนี้แนะนำให้สร้าง index บนฟิลด์ <code>customer ID</code> ใน <code>transactions</code> collection [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1921" target="_blank" rel="noopener noreferrer">32:01</a>]</li></ul></li><li><strong>การตรวจสอบผลลัพธ์</strong>: หลังจากสร้าง index แล้ว latency บน <code>transactions</code> collection ก็ลดลงอย่างเห็นได้ชัด [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1972" target="_blank" rel="noopener noreferrer">32:52</a>]</li></ul><h4 id="_2-index-การใช้งาน-index" tabindex="-1"><a class="header-anchor" href="#_2-index-การใช้งาน-index"><span>2. Index (การใช้งาน Index)</span></a></h4><p>Xen ได้อธิบายถึงการใช้ index เพื่อเพิ่มประสิทธิภาพ query [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=750" target="_blank" rel="noopener noreferrer">12:30</a>]</p><ul><li><strong>ปัญหา</strong>: Index ช่วยเร่งความเร็ว query แต่ก็ใช้ resource (CPU, IO, storage, cache space) และทำให้ write performance ช้าลง [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=761" target="_blank" rel="noopener noreferrer">12:41</a>] การเพิ่ม index ทุกครั้งอาจส่งผลกระทบต่อ write performance 5% - 75% [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=810" target="_blank" rel="noopener noreferrer">13:30</a>]</li><li><strong>ข้อขัดแย้ง</strong>: ต้องการ index เพื่อเพิ่มประสิทธิภาพ query แต่ก็ต้องรักษาสมดุลกับ resource usage และ write performance [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=852" target="_blank" rel="noopener noreferrer">14:12</a>] การออกแบบ index ที่เหมาะสมสำหรับ query ที่ซับซ้อนเป็นเรื่องยาก [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=878" target="_blank" rel="noopener noreferrer">14:38</a>]</li><li><strong>แนวทางแก้ไข</strong>: <ul><li><p><strong><code>explain</code> command</strong>: ใช้เพื่อตรวจสอบว่า query ใช้ index ใด และแผนการทำงานของ query มีประสิทธิภาพแค่ไหน (ดูจากจำนวน documents ที่ scan และจำนวน fetch) [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=898" target="_blank" rel="noopener noreferrer">14:58</a>]</p></li><li><p><strong>Testing</strong>: ทดลองสร้าง index ที่แตกต่างกันบน test clusters และ monitor slow queries หลังจากการ drop index [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=926" target="_blank" rel="noopener noreferrer">15:26</a>]</p></li><li><p><strong>Hide Index (ใน Atlas)</strong>: สามารถซ่อน index แทนการ drop เพื่อประหยัดเวลาในการ recreate หากต้องการนำกลับมาใช้ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=944" target="_blank" rel="noopener noreferrer">15:44</a>]</p></li><li><p><strong>Performance Advisor (ใน Atlas)</strong>: ช่วย monitor การใช้งาน index และแนะนำ index ที่ควรสร้าง [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=951" target="_blank" rel="noopener noreferrer">15:51</a>]</p></li><li><p><strong>Compound Index</strong>: ใช้เพื่อปรับปรุงประสิทธิภาพของ query ที่ซับซ้อน [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=972" target="_blank" rel="noopener noreferrer">16:12</a>]</p></li><li><p><strong>Persistent Query Settings (ฟีเจอร์ใหม่ใน MongoDB 7.0)</strong>: อนุญาตให้ตั้งค่า query settings รวมถึง index hints ให้คงอยู่แม้จะมีการ restart หรือ upgrade instance [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1008" target="_blank" rel="noopener noreferrer">16:48</a>] ทำให้ query engine ใช้ index ที่ระบุ แทนที่จะเลือกเอง [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1032" target="_blank" rel="noopener noreferrer">17:12</a>]</p></li><li><p><strong>Demo การใช้ Persistent Query Settings</strong>:</p><ul><li>สถานการณ์: ต้องการค้นหาข้อมูลผู้เสียภาษีที่เป็น <code>Pirates</code> และเสียภาษีระหว่าง 50-500 gold coins [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1042" target="_blank" rel="noopener noreferrer">17:22</a>]</li><li>เริ่มต้นด้วยการลบ query settings, drop indexes และลบข้อมูลทั้งหมด [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1103" target="_blank" rel="noopener noreferrer">18:23</a>]</li><li>Insert ข้อมูลตัวอย่าง: 1,000 <code>Pirates</code> ที่เสียภาษี 0-100 coins, 10,000 <code>Ordinary People</code> ที่เสียภาษี 90-1000 coins, และ 10 <code>Pirates</code> ที่เสียภาษี 800-2000 coins [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1123" target="_blank" rel="noopener noreferrer">18:43</a>]</li><li>สร้าง index บนฟิลด์ <code>tax</code> และ <code>occupation</code> [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1183" target="_blank" rel="noopener noreferrer">19:43</a>]</li><li>รัน query แรก: พบว่า query engine ใช้ <code>tax</code> index และ scan ไป 5,068 documents ซึ่งไม่มีประสิทธิภาพ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1223" target="_blank" rel="noopener noreferrer">20:23</a>]</li><li>Apply <code>persistent query setting</code>: บังคับให้ query engine ใช้ <code>occupation</code> index แทน [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1273" target="_blank" rel="noopener noreferrer">21:13</a>]</li><li>รัน query ซ้ำ: พบว่า query engine ใช้ <code>occupation</code> index และ scan เพียง 1,000 documents ทำให้มีประสิทธิภาพมากขึ้น [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1317" target="_blank" rel="noopener noreferrer">21:57</a>]</li><li>Query settings จะถูก apply กับ <code>query shape</code> ซึ่งไม่ขึ้นกับค่า literal ทำให้ query ที่มีโครงสร้างคล้ายกันได้รับผลประโยชน์ด้วย [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=1340" target="_blank" rel="noopener noreferrer">22:20</a>]</li></ul></li></ul></li></ul><h4 id="_3-design-schema-การออกแบบ-schema" tabindex="-1"><a class="header-anchor" href="#_3-design-schema-การออกแบบ-schema"><span>3. Design Schema (การออกแบบ Schema)</span></a></h4><p>Xen ได้กล่าวถึงความสำคัญของการออกแบบ schema ใน MongoDB [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2050" target="_blank" rel="noopener noreferrer">34:10</a>]</p><ul><li><strong>ความเข้าใจผิด</strong>: MongoDB ไม่ได้เป็น &quot;no schema database&quot; แต่เป็น &quot;flexible schema&quot; database [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2081" target="_blank" rel="noopener noreferrer">34:41</a>] การออกแบบ schema ที่ดีและเหมาะสมกับ query shapes เป็นสิ่งสำคัญสำหรับการได้ประสิทธิภาพสูงสุด [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2114" target="_blank" rel="noopener noreferrer">35:14</a>]</li><li><strong>ข้อขัดแย้ง</strong>: <ul><li><strong>Flexible Schema</strong>: ยืดหยุ่นในการจัดเก็บข้อมูล (Arrays, Sub-documents, Key-value pairs) และสามารถแก้ไข schema ได้โดยไม่ต้อง downtime [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2145" target="_blank" rel="noopener noreferrer">35:45</a>]</li><li><strong>Simplicity</strong>: แอปพลิเคชัน MongoDB มักมี collections น้อยกว่า tables ใน relational database [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2175" target="_blank" rel="noopener noreferrer">36:15</a>]</li><li><strong>Cost</strong>: การปรับปรุงประสิทธิภาพอาจนำมาซึ่งต้นทุนที่สูงขึ้น เช่น การ duplicate ข้อมูล [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2194" target="_blank" rel="noopener noreferrer">36:34</a>]</li></ul></li><li><strong>แนวทางแก้ไข</strong>: <ul><li><strong>Query-Driven Design</strong>: ออกแบบ schema โดยคำนึงถึง query ที่จะรันเป็นหลัก ไม่ใช่จากข้อมูลที่มีอยู่ [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2214" target="_blank" rel="noopener noreferrer">36:54</a>]</li><li><strong>Embedding vs. Referencing</strong>: ตัดสินใจว่าจะใช้ embedded sub-documents หรือเก็บข้อมูลใน collections แยกกัน แล้วใช้ <code>$lookup</code> ในการเชื่อมโยง [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2244" target="_blank" rel="noopener noreferrer">37:24</a>] <ul><li><strong>ตัวอย่าง Book and Comments</strong>: <ul><li><strong>Embedding</strong>: เก็บ comments ใน array ภายใน document ของ books ทำให้ดึงข้อมูลได้เร็ว แต่ถ้า comments มีจำนวนมาก อาจดึงข้อมูลเกินความจำเป็น [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2272" target="_blank" rel="noopener noreferrer">37:52</a>]</li><li><strong>Referencing</strong>: แยก books และ reviews ออกเป็นคนละ collection ทำให้ดึงข้อมูล books ได้เร็วขึ้น แต่ต้องทำ <code>$lookup</code> เพื่อดึง comments [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2291" target="_blank" rel="noopener noreferrer">38:11</a>]</li><li><strong>Hybrid</strong>: เก็บ 5-10 comments ล่าสุดแบบ embedding และเก็บ comments ที่เหลือใน collection แยก [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2342" target="_blank" rel="noopener noreferrer">39:02</a>]</li></ul></li></ul></li><li><strong>Memory Sizing</strong>: กำหนด working set ของข้อมูลที่ต้องการให้อยู่ใน memory (cache) เพื่อให้เข้าถึงได้เร็วโดยไม่ต้องดึงจาก disk [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2401" target="_blank" rel="noopener noreferrer">40:01</a>] <ul><li><strong>ตัวอย่างเกมมือถือ</strong>: คำนวณ memory ที่จำเป็นสำหรับ system data, indexes และ player data [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2420" target="_blank" rel="noopener noreferrer">40:20</a>] โดย MongoDB จะจัดสรร 50% ของ physical memory ให้กับ cache [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2440" target="_blank" rel="noopener noreferrer">40:40</a>]</li></ul></li></ul></li></ul><p>ผู้บรรยายได้สรุปว่าหวังว่าผู้ชมจะได้รับความรู้และแนวทางปฏิบัติที่เป็นประโยชน์ในการปรับแต่งประสิทธิภาพของ database [<a href="http://www.youtube.com/watch?v=xY2NwsYHpV4&amp;t=2480" target="_blank" rel="noopener noreferrer">41:20</a>] และได้ให้ QR Code</p>`,20)]])}var c=i(o,[[`render`,s]]);export{a as _pageData,c as default};